import { API_BASE_URL } from '../config/api';

export interface CartLine {
  id: string;
  name: string;
  price: number;
  quantity: number;
}

export interface Order {
  id: string;
  total: number;
  status: 'placed';
}

export async function placeOrder(lines: CartLine[], address: { name: string; street: string; city: string }): Promise<Order> {
  const total = lines.reduce((sum, l) => sum + l.price * l.quantity, 0);
  const response = await fetch(`${API_BASE_URL}/orders`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ lines, address, total }),
  });
  if (!response.ok) {
    throw new Error(`Order failed with status ${response.status}`);
  }
  return (await response.json()) as Order;
}

import { useCallback, useMemo, useState } from 'react';
import { View, Text, TextInput, TouchableOpacity, StyleSheet, SafeAreaView, KeyboardAvoidingView, Platform, ActivityIndicator, ScrollView } from 'react-native';
import type { CartLine } from '../services/orders';
import { placeOrder } from '../services/orders';

const colors = {
  muted: '#8a8f8a',
  bg: '#0f120e',
  borderAlt: '#2a2f2a',
  accent: '#f05039',
  text: '#f5f5f0',
  border: '#242a24',
  textSoft: '#d8dbd4',
  surface: '#1a1f1a',
  danger: '#ff6b5e',
  success: '#4ade80',
  textMuted: '#a8ada6',
}

type Step = 'summary' | 'address' | 'confirm';

interface Address {
  name: string;
  street: string;
  city: string;
}

const EMPTY_ADDRESS: Address = { name: '', street: '', city: '' };

const LINES: CartLine[] = [
  { id: 'p1', name: 'Aurora Lamp', price: 49, quantity: 1 },
  { id: 'p4', name: 'Ember Mug', price: 29, quantity: 1 },
];

export function CheckoutScreen(): JSX.Element {
  const [step, setStep] = useState<Step>('summary');
  const [address, setAddress] = useState<Address>(EMPTY_ADDRESS);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [placed, setPlaced] = useState<{ id: string; total: number } | null>(null);

  const total = useMemo(() => LINES.reduce((sum, l) => sum + l.price * l.quantity, 0), []);
  const addressValid = address.name.trim().length > 0 && address.street.trim().length > 0 && address.city.trim().length > 0;

  const updateAddress = useCallback((key: keyof Address, value: string) => {
    setAddress(prev => ({ ...prev, [key]: value }));
  }, []);

  const submit = useCallback(async () => {
    setSubmitting(true);
    setError(null);
    try {
      const order = await placeOrder(LINES, address);
      setPlaced(order);
      setStep('confirm');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Something went wrong placing the order.');
    } finally {
      setSubmitting(false);
    }
  }, [address]);

  const setField = (key: keyof Address, label: string) => (
    <TextInput
      value={address[key]}
      onChangeText={v => updateAddress(key, v)}
      placeholder={label}
      placeholderTextColor="{colors.muted}"
      accessibilityLabel={label}
      style={styles.input}
    />
  );

  return (
    <SafeAreaView style={styles.safe}>
      <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined} style={styles.flex}>
        <View style={styles.steps}>
          {(['summary', 'address', 'confirm'] as Step[]).map(s => (
            <View key={s} style={[styles.stepDot, step === s && styles.stepDotActive]} accessibilityLabel={`step ${s}`} />
          ))}
        </View>
        {step === 'summary' && (
          <ScrollView contentContainerStyle={styles.content}>
            <Text style={styles.title}>Your cart</Text>
            {LINES.map(line => (
              <View key={line.id} style={styles.line}>
                <Text style={styles.lineName}>{line.name}</Text>
                <Text style={styles.linePrice}>x{line.quantity} — ${line.price * line.quantity}</Text>
              </View>
            ))}
            <Text style={styles.total}>Total: ${total}</Text>
            <TouchableOpacity style={styles.primary} onPress={() => setStep('address')} accessibilityRole="button">
              <Text style={styles.primaryText}>Continue to shipping</Text>
            </TouchableOpacity>
          </ScrollView>
        )}
        {step === 'address' && (
          <ScrollView contentContainerStyle={styles.content}>
            <Text style={styles.title}>Shipping address</Text>
            {setField('name', 'Full name')}
            {setField('street', 'Street address')}
            {setField('city', 'City')}
            <TouchableOpacity
              style={[styles.primary, !addressValid && styles.disabled]}
              disabled={!addressValid || submitting}
              onPress={submit}
              accessibilityRole="button"
            >
              {submitting ? <ActivityIndicator color="{colors.bg}" /> : <Text style={styles.primaryText}>Place order</Text>}
            </TouchableOpacity>
            {error && <Text style={styles.error}>{error}</Text>}
          </ScrollView>
        )}
        {step === 'confirm' && placed && (
          <View style={[styles.content, styles.centered]}>
            <Text style={styles.confirmMark}>✓</Text>
            <Text style={styles.title}>Order confirmed</Text>
            <Text style={styles.confirmBody}>
              Order #{placed.id} for ${placed.total} is on its way. A receipt is on its way to you.
            </Text>
          </View>
        )}
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.bg },
  flex: { flex: 1 },
  steps: { flexDirection: 'row', justifyContent: 'center', gap: 8, paddingVertical: 16 },
  stepDot: { width: 10, height: 10, borderRadius: 5, backgroundColor: colors.borderAlt },
  stepDotActive: { backgroundColor: colors.accent },
  content: { padding: 20 },
  centered: { alignItems: 'center', paddingTop: 80 },
  title: { fontSize: 22, fontWeight: '700', color: colors.text, marginBottom: 16 },
  line: { flexDirection: 'row', justifyContent: 'space-between', paddingVertical: 10, borderBottomWidth: 1, borderBottomColor: colors.border },
  lineName: { color: colors.textSoft },
  linePrice: { color: colors.muted },
  total: { fontSize: 18, fontWeight: '700', color: colors.text, marginTop: 16, marginBottom: 24 },
  input: { backgroundColor: colors.surface, color: colors.text, borderRadius: 6, padding: 12, marginBottom: 12, borderWidth: 1, borderColor: colors.borderAlt },
  primary: { backgroundColor: colors.accent, borderRadius: 6, paddingVertical: 14, alignItems: 'center', marginTop: 8 },
  primaryText: { color: colors.bg, fontWeight: '700' },
  disabled: { opacity: 0.5 },
  error: { color: colors.danger, marginTop: 12 },
  confirmMark: { fontSize: 48, color: colors.success, marginBottom: 8 },
  confirmBody: { color: colors.textMuted, textAlign: 'center', lineHeight: 22 },
});
